+        background: rgba(15, 23, 42, 0.78);
+        border: 1px solid var(--border);
+        border-radius: 1rem;
+      }
+
+      .checkbox-row {
+        display: flex;
+        align-items: flex-start;
+        gap: 0.8rem;
+      }
+
+      input[type="checkbox"] {
+        width: 1.35rem;
+        height: 1.35rem;
+        flex: 0 0 auto;
+        margin: 0.15rem 0 0;
+        accent-color: var(--accent-strong);
+        cursor: pointer;
+      }
+
+      label {
+        font-weight: 700;
+        cursor: pointer;
+      }
+
+      .required-marker {
+        color: var(--accent);
+      }
+
+      .helper {
+        color: var(--muted);
+        font-size: 0.95rem;
+      }
+
+      .error {
+        color: var(--error);
+        font-weight: 700;
+      }
+
+      button {
+        min-height: 3rem;
+        padding: 0.85rem 1.25rem;
+        color: #03111d;
