+        <p class="intro">Confirm your consent before continuing.</p>
+
+        <form id="consent-form" novalidate>
+          <p class="required-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>
+
+          <div class="form-field">
+            <div class="checkbox-row">
+              <input
+                id="terms-consent"
+                name="termsConsent"
+                type="checkbox"
+                required
+                aria-describedby="terms-help terms-error">
+              <label for="terms-consent">
+                I agree to the terms of use <span class="required-marker" aria-hidden="true">*</span>
+              </label>
+            </div>
+            <p id="terms-help" class="helper">Required to submit this form.</p>
+            <p id="terms-error" class="error" hidden>Error: You must agree to the terms of use to continue.</p>
