      <section class="card" aria-labelledby="form-title">
        <h1 id="form-title">Review terms</h1>
        <p class="intro">Confirm your consent before continuing.</p>

        <form id="consent-form" novalidate>
          <p class="required-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>

          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="terms-consent"
                name="termsConsent"
                type="checkbox"
                required
                aria-describedby="terms-help terms-error">
              <label for="terms-consent">
                I agree to the terms of use <span class="required-marker" aria-hidden="true">*</span>
              </label>
            </div>
            <p id="terms-help" class="helper">Required to submit this form.</p>
            <p id="terms-error" class="error" hidden>Error: You must agree to the terms of use to continue.</p>
          </div>

          <button type="submit">Agree and continue</button>
          <p id="form-status" class="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#consent-form");
      const checkbox = document.querySelector("#terms-consent");
      const error = document.querySelector("#terms-error");
      const status = document.querySelector("#form-status");

      function showError() {
        checkbox.setAttribute("aria-invalid", "true");
        error.hidden = false;
        status.textContent = "";
      }

      function clearError() {
        checkbox.removeAttribute("aria-invalid");
        error.hidden = true;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          showError();
          checkbox.focus();
          return;
        }

        clearError();
        status.textContent = "Thanks. Your consent has been recorded.";
      });

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          clearError();
        }
      });
    </script>
